#include <iostream>
#include <type_traits>

namespace my
{
    template <typename A, typename B>
    struct is_same { static constexpr bool value{ false }; };

    template <typename A>
    struct is_same<A, A> { static constexpr bool value{ true }; };      // the specialisation wins when both are the same

    template <typename A, typename B>
    inline constexpr bool is_same_v{ is_same<A, B>::value };

    template <typename T>
    struct remove_const { using type = T; };

    // TODO: the specialisation of remove_const for const T, and remove_const_t
    // TODO: remove_reference (two specialisations: T& and T&&), is_pointer, conditional
}

static_assert(my::is_same_v<int, int>);
static_assert(!my::is_same_v<int, long>);

int main()
{
    std::cout << "every static_assert passed, or this would not have compiled\n";
    return 0;
}
